 void scan(Canvas c){top(c,"Cihaz Algılanıyor");text(c,scanning?"Yakındaki cihazlar taranıyor…":"Tarama tamamlandı",195,108,13,MUTED,Paint.Align.CENTER,false);text(c,scanning?"Lütfen bekleyin.":cap(),195,128,11,MUTED,Paint.Align.CENTER,false);float cx=195,cy=245;for(int i=1;i<=4;i++){st.setStrokeWidth(1.2f);st.setColor(Color.rgb(35+i*4,58+i*5,72+i*4));c.drawCircle(cx,cy,i*30,st);}if(scanning){float ang=(System.currentTimeMillis()%3000)/3000f*360;Path q=new Path();q.moveTo(cx,cy);for(int d=0;d<=44;d+=4){double r=Math.toRadians(ang-d);q.lineTo(cx+(float)Math.cos(r)*120,cy+(float)Math.sin(r)*120);}q.close();p.setColor(0x442CB6FF);c.drawPath(q,p);}p.setColor(BLUE);c.drawCircle(cx,cy,5,p);float y=388;if(found.isEmpty()){row(c,y,"Samsung TV","Örnek • tarama sonucunda değişir");row(c,y+64,"LG Klima","Örnek • yerel profil");row(c,y+128,"Sony Ses Sistemi","Örnek • ağ cihazı");}else for(int i=0;i<Math.min(5,found.size());i++)row(c,y+i*64,found.get(i),"Yerel ağda bulundu");nav(c,1);}
