 void say(String z){toast=z;toastUntil=System.currentTimeMillis()+2200;invalidate();}
 void go(S n){s=n;if(n==S.SCAN)discover();invalidate();}
 void send(String act){if(!hasIr()){say("IR vericisi yok • WiFi cihazı seç");return;}String code=null;if(brand.equals("Samsung")){switch(act){case"POWER":code="E0E040BF";break;case"VU":code="E0E0E01F";break;case"VD":code="E0E0D02F";break;case"CU":code="E0E048B7";break;case"CD":code="E0E008F7";break;case"M":code="E0E0F00F";break;case"S":code="E0E0807F";break;case"U":code="E0E006F9";break;case"D":code="E0E08679";break;case"L":code="E0E0A659";break;case"R":code="E0E046B9";break;case"OK":code="E0E016E9";break;}}else if(brand.equals("LG")){switch(act){case"POWER":code="20DF10EF";break;case"VU":code="20DF40BF";break;case"VD":code="20DFC03F";break;case"CU":code="20DF00FF";break;case"CD":code="20DF807F";break;case"M":code="20DF906F";break;case"S":code="20DFD02F";break;case"U":code="20DF02FD";break;case"D":code="20DF827D";break;case"L":code="20DFE01F";break;case"R":code="20DF609F";break;case"OK":code="20DF22DD";break;}}if(code==null){say("Bu marka/komut için IR profili yok");return;}try{long v=Long.parseUnsignedLong(code,16);int[]a=new int[67];a[0]=brand.equals("Samsung")?4500:9000;a[1]=4500;int q=2;for(int bi=3;bi>=0;bi--){int by=(int)((v>>(bi*8))&255);for(int bit=0;bit<8;bit++){a[q++]=560;a[q++]=((by>>bit)&1)==1?1690:560;}}a[66]=560;ir.transmit(38000,a);say(brand+" • komut gönderildi");}catch(Exception e){say("IR gönderimi başarısız");}}
 void discover(){if(scanning)return;found.clear();scanning=true;new Thread(()->{if(!wifi()){h.post(()->{scanning=false;say("WiFi bağlı değil");});return;}WifiManager.MulticastLock lock=null;DatagramSocket ds=null;try{WifiManager wm=(WifiManager)ctx.getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wm!=null){lock=wm.createMulticastLock("ibo");lock.setReferenceCounted(false);lock.acquire();}ds=new DatagramSocket();ds.setSoTimeout(500);byte[]b=("M-SEARCH * HTTP/1.1\r\nHOST:239.255.255.250:1900\r\nMAN:\"ssdp:discover\"\r\nMX:2\r\nST:ssdp:all\r\n\r\n").getBytes(StandardCharsets.UTF_8);ds.send(new DatagramPacket(b,b.length,InetAddress.getByName("239.255.255.250"),1900));long end=System.currentTimeMillis()+2400;HashSet<String> seen=new HashSet<>();while(System.currentTimeMillis()<end){try{byte[]buf=new byte[4096];DatagramPacket d=new DatagramPacket(buf,buf.length);ds.receive(d);String ip=d.getAddress().getHostAddress();if(seen.add(ip))h.post(()->{found.add("Ağ Cihazı • "+ip);invalidate();});}catch(SocketTimeoutException e){}}}catch(Exception e){}finally{if(ds!=null)ds.close();if(lock!=null&&lock.isHeld())lock.release();h.post(()->{scanning=false;say(found.isEmpty()?"Cihaz bulunamadı":found.size()+" cihaz bulundu");invalidate();});}},"ibo-scan").start();}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=(e.getX()-ox)/sc,y=(e.getY()-oy)/sc;if(y>706){if(x<97)go(S.HOME);else if(x<195)go(S.SCAN);else if(x<292)go(S.SCENES);else go(S.SETTINGS);return true;}if(x<60&&y<105&&s!=S.HOME){go(S.HOME);return true;}switch(s){case HOME:if(y>150&&y<295)go(x<195?S.TV:S.CLIMATE);else if(y>295&&y<560)go(S.BRANDS);else if(y<110&&x>340)go(S.SETTINGS);break;case TV:tvTouch(x,y);break;case CLIMATE:if(y>315&&y<385){if(x<130)temp=Math.max(16,temp-1);else if(x>260)temp=Math.min(30,temp+1);say(temp+"°C");invalidate();}break;case BRANDS:if(y>=170&&y<=490){String[][]br={{"Samsung","LG","Sony"},{"Philips","Vestel","Beko"},{"Arçelik","Toshiba","Panasonic"},{"Daikin","Mitsubishi","Bosch"},{"Siemens","Sharp","Haier"}};int r=Math.min(4,Math.max(0,(int)((y-170)/64))),co=Math.min(2,Math.max(0,(int)((x-20)/119)));brand=br[r][co];say(brand+" seçildi");go((brand.equals("Daikin")||brand.equals("Mitsubishi"))?S.CLIMATE:S.TV);}break;case SCENES:if(y>100&&y<540)say("Sahne çalıştırıldı");break;case SETTINGS:if(y>245&&y<325)go(S.SCAN);break;default:break;}return true;}
 void tvTouch(float x,float y){float dx=x-195,dy=y-240,r=dx*dx+dy*dy;if(r<1600){send("OK");return;}if(r<10000){send(Math.abs(dx)>Math.abs(dy)?(dx<0?"L":"R"):(dy<0?"U":"D"));return;}if(x<65&&y>180&&y<310){if(y<235)send("VU");else if(y>265)send("VD");return;}if(x>325&&y>180&&y<310){if(y<235)send("CU");else if(y>265)send("CD");return;}if(y>520&&y<600){if(x>130&&x<255)send("M");else if(x>250)send("S");}}
